(()=>{"use strict";(()=>{const e=document.getElementById("timer-hours"),t=document.getElementById("timer-minutes"),n=document.getElementById("timer-seconds"),m=()=>{let o=(()=>{let e=(new Date("22 september 2026").getTime()-(new Date).getTime())/1e3;return{timeRemaining:e,hours:Math.floor(e/60/60),minutes:Math.floor(e/60%60),seconds:Math.floor(e%60)}})();e.textContent=o.hours,t.textContent=o.minutes,n.textContent=o.seconds,o.timeRemaining>0&&setTimeout(m,1e3)};m()})()})();